css:
.d1127-rug,.d1127-man,.d1127-fist{transform-box:fill-box}
.d1127-rug{animation:d1127-a 3.6s ease-in-out infinite}
.d1127-man{transform-origin:50% 100%;animation:d1127-b 3.6s ease-in-out infinite}
.d1127-fist{animation:d1127-c 3s ease-in-out infinite}
@keyframes d1127-a{0%,20%{transform:translateX(0)}50%,100%{transform:translateX(-80px)}}
@keyframes d1127-b{0%,40%{transform:translate(0,0) rotate(0)}70%,100%{transform:translate(0,22px) rotate(-70deg)}}
@keyframes d1127-c{0%,100%{transform:translateX(0)}40%{transform:translateX(50px)}55%{transform:translateX(20px)}}
@media (prefers-reduced-motion:reduce){.d1127-rug{transform:translateX(-80px)}.d1127-man{transform:translate(0,22px) rotate(-70deg)}.d1127-fist{transform:translateX(50px)}}
